ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
var queryParams = attributes.queryParams
var separateDate = splitBy((splitBy(queryParams.FechaExpedicion," ")[0]),"/")
var date= separateDate[2] ++ "-" ++ separateDate[1] ++ "-" ++ separateDate[0]
var time=  ( (queryParams.FechaExpedicion splitBy (" "))[1] as Time) as String {format: "HH:mm:ss.SSSS"}
var datetime= date ++ "T" ++ time
---
soapenv#Envelope:{
    soapenv#Header:{},
    soapenv#Body:{
        tem#ObtenerCuestionario:{
            //Optional
            tem#objSolicitud: {
                //Optional
                tem#Usuario: p('lisim.usuario'),
                //Optional
                tem#Contrasena: p('lisim.contrasena'),
                //Optional
                tem#TipoIdentificacion: 
                (
                	if(queryParams.TipoIdentificacion == "CC")
                		1
                	else if(queryParams.TipoIdentificacion == "CE")
                		2
                	else
                		9             
                )
                ,
                //Optional
                tem#Identificacion: queryParams.Identificacion default "",
                //Optional
                tem#Apellido: queryParams.Apellido default "",
                tem#FechaExpedicion: datetime,
                tem#Modelo: queryParams.Modelo default "",
                tem#Departamento: queryParams.Departamento default "",
                tem#Ciudad: queryParams.Ciudad default "",
                //Optional
                tem#Asesor: queryParams.Asesor default "",
                //Optional
                tem#CanalVenta: queryParams.CanalVenta default "",
                //Optional
                tem#Proveedor: queryParams.Proveedor default "",
                //Optional
                tem#Portal: queryParams.Portal default "",
            }
        }
    }   
}
